// TaskCommentsPage.js
import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

/* ----------------------------------------------------
   PARTICLES (MyStudiesPage / ManageEvaluationTasksPage ile aynı)
----------------------------------------------------- */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);

    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

function TaskCommentsPage() {
    const { taskId } = useParams();
    const navigate = useNavigate();

    const [comments, setComments] = useState([]);
    const [deletedLogs, setDeletedLogs] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filterUsername, setFilterUsername] = useState("");
    const [activeTab, setActiveTab] = useState("comments");
    const [researcherLogs, setResearcherLogs] = useState([]);
    const [filtersOpen, setFiltersOpen] = useState(false);

    // ------------------------
    // LOAD COMMENTS
    // ------------------------
    const loadComments = async () => {
        try {
            const token = localStorage.getItem("token");

            const [activeRes, deletedRes] = await Promise.all([
                fetch(`http://localhost:8080/api/comments/task/${taskId}`, {
                    headers: { Authorization: `Bearer ${token}` }
                }),
                fetch(`http://localhost:8080/api/comments/task/${taskId}/deleted`, {
                    headers: { Authorization: `Bearer ${token}` }
                })
            ]);

            const activeData = await activeRes.json();
            const deletedData = await deletedRes.json();

            setComments(activeData);
            setDeletedLogs(deletedData);

        } catch (e) {
            console.error("❌ Failed to load comments:", e);
        } finally {
            setLoading(false);
        }
    };

    // ------------------------
    // LOAD RESEARCHER LOGS
    // ------------------------
    const loadResearcherLogs = async () => {
        try {
            const token = localStorage.getItem("token");

            const res = await fetch(
                `http://localhost:8080/api/comments/task/${taskId}/researcher-logs`,
                {
                    headers: { Authorization: `Bearer ${token}` }
                }
            );

            const data = await res.json();
            setResearcherLogs(data);

        } catch (err) {
            console.error("❌ Failed to load researcher logs:", err);
        }
    };

    useEffect(() => {
        loadComments();
        loadResearcherLogs();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [taskId]);

    // ------------------------
    // DELETE COMMENT
    // ------------------------
    const deleteComment = async (id) => {
        if (!window.confirm("Delete this comment?")) return;

        try {
            const token = localStorage.getItem("token");

            await fetch(`http://localhost:8080/api/comments/${id}`, {
                method: "DELETE",
                headers: { Authorization: `Bearer ${token}` }
            });

            await loadComments();
        } catch (e) {
            console.error("❌ Delete failed:", e);
        }
    };

    // ------------------------
    // GROUP BY ARTIFACT FIELD CODE
    // ------------------------
    const grouped = {};
    comments.forEach((c) => {
        if (!c.deleted) {
            if (!grouped[c.fieldCode]) grouped[c.fieldCode] = [];
            grouped[c.fieldCode].push(c);
        }
    });

    // ------------------------
    // PIN / UNPIN
    // ------------------------
    const togglePin = async (id) => {
        try {
            const token = localStorage.getItem("token");

            const res = await fetch(
                `http://localhost:8080/api/comments/${id}/pin`,
                {
                    method: "PUT",
                    headers: { Authorization: `Bearer ${token}` }
                }
            );

            const updated = await res.json();

            setComments(prev =>
                prev.map(c => (c.id === id ? updated : c))
            );
        } catch (e) {
            console.error("❌ Pin toggle failed:", e);
        }
    };

    // ------------------------
    // FILTER BY PARTICIPANT USERNAME
    // ------------------------
    const filterByParticipant = async () => {
        if (!filterUsername.trim()) {
            loadComments();
            return;
        }

        try {
            const token = localStorage.getItem("token");

            const res = await fetch(
                `http://localhost:8080/api/comments/task/${taskId}/participant/${filterUsername}`,
                {
                    headers: { Authorization: `Bearer ${token}` }
                }
            );

            const data = await res.json();
            setComments(data);
        } catch (err) {
            console.error("❌ Filter failed:", err);
        }
    };

    return (
        <div style={styles.container}>
            <FloatingParticles />

            {/* NAVBAR — ManageEvaluationTasksPage teması */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>
                    <span>💬</span>
                    <span>Task Comments — #{taskId}</span>
                </h2>

                <button
                    style={styles.backButton}
                    onMouseEnter={(e) => {
                        e.currentTarget.style.transform = "scale(1.05)";
                        e.currentTarget.style.boxShadow =
                            "0 0 18px rgba(220,38,38,0.7)";
                    }}
                    onMouseLeave={(e) => {
                        e.currentTarget.style.transform = "scale(1)";
                        e.currentTarget.style.boxShadow =
                            "0 0 12px rgba(220,38,38,0.4)";
                    }}
                    onClick={() => navigate(-1)}
                >
                    ← Back
                </button>
            </div>

            <div style={styles.centerWrapper}>
                {loading ? (
                    <p style={styles.loading}>Loading comments...</p>
                ) : (
                    <>
                        {/* TAB BAR */}
                        <div style={styles.tabBar}>
                            <button
                                style={
                                    activeTab === "comments"
                                        ? styles.activeTabButton
                                        : styles.tabButton
                                }
                                onClick={() => setActiveTab("comments")}
                            >
                                💬 Comments
                            </button>
                            <button
                                style={
                                    activeTab === "logs"
                                        ? styles.activeTabButton
                                        : styles.tabButton
                                }
                                onClick={() => setActiveTab("logs")}
                            >
                                📄 Researcher Action Logs
                            </button>
                        </div>

                        {activeTab === "comments" && (
                            <>
                                {/* FILTER WRAPPER (katlanır panel) */}
                                <div style={styles.filterWrapper}>
                                    <button
                                        style={styles.filterToggle}
                                        onClick={() =>
                                            setFiltersOpen((prev) => !prev)
                                        }
                                    >
                                        {filtersOpen
                                            ? "▲ Filter by participant"
                                            : "▼ Filter by participant"}
                                    </button>

                                    <div
                                        style={{
                                            ...styles.filterPanel,
                                            maxHeight: filtersOpen
                                                ? "200px"
                                                : "0px",
                                            padding: filtersOpen
                                                ? "16px 18px 18px 18px"
                                                : "0 18px",
                                            opacity: filtersOpen ? 1 : 0,
                                        }}
                                    >
                                        <div style={styles.filterContentRow}>
                                            {/* USERNAME INPUT */}
                                            <div style={styles.searchContainer}>
                                                <span style={styles.searchIcon}>
                                                    👤
                                                </span>
                                                <input
                                                    type="text"
                                                    placeholder="Participant username..."
                                                    value={filterUsername}
                                                    onChange={(e) =>
                                                        setFilterUsername(
                                                            e.target.value
                                                        )
                                                    }
                                                    style={styles.searchInput}
                                                />
                                            </div>

                                            <div style={styles.filterButtonsRow}>
                                                <button
                                                    onClick={filterByParticipant}
                                                    style={
                                                        styles.filterButtonPrimary
                                                    }
                                                >
                                                    Apply Filter
                                                </button>

                                                <button
                                                    onClick={loadComments}
                                                    style={
                                                        styles.filterButtonSecondary
                                                    }
                                                >
                                                    Reset
                                                </button>
                                            </div>
                                        </div>
                                        <p style={styles.smallHint}>
                                            Filter uses server-side query, so it
                                            will only return comments from that
                                            participant on this task.
                                        </p>
                                    </div>
                                </div>

                                {/* COMMENTS CONTENT */}
                                {Object.keys(grouped).length === 0 ? (
                                    <p style={styles.noComments}>
                                        No comments found.
                                    </p>
                                ) : (
                                    <div style={styles.groupsGrid}>
                                        {Object.keys(grouped).map((field) => (
                                            <div
                                                key={field}
                                                style={styles.groupBox}
                                            >
                                                <div
                                                    style={
                                                        styles.groupHeaderRow
                                                    }
                                                >
                                                    <h3
                                                        style={
                                                            styles.groupTitle
                                                        }
                                                    >
                                                        Artifact: {field}
                                                    </h3>
                                                    <span
                                                        style={
                                                            styles.groupBadge
                                                        }
                                                    >
                                                        {grouped[field].length}{" "}
                                                        message
                                                        {grouped[field].length >
                                                        1
                                                            ? "s"
                                                            : ""}
                                                    </span>
                                                </div>

                                                <div style={styles.chatBox}>
                                                    {grouped[field]
                                                        .sort(
                                                            (a, b) =>
                                                                (b.pinned ===
                                                                    true) -
                                                                (a.pinned ===
                                                                    true)
                                                        )
                                                        .map((c) => (
                                                            <div
                                                                key={c.id}
                                                                style={
                                                                    styles.message
                                                                }
                                                            >
                                                                <div
                                                                    style={
                                                                        styles.headerRow
                                                                    }
                                                                >
                                                                    <span
                                                                        style={
                                                                            styles.username
                                                                        }
                                                                    >
                                                                        @
                                                                        {
                                                                            c.username
                                                                        }
                                                                    </span>
                                                                    <span
                                                                        style={
                                                                            styles.time
                                                                        }
                                                                    >
                                                                        {
                                                                            c.createdAt
                                                                        }
                                                                    </span>
                                                                </div>

                                                                <div
                                                                    style={
                                                                        c.pinned
                                                                            ? styles.pinnedBubble
                                                                            : styles.bubble
                                                                    }
                                                                >
                                                                    {c.content}
                                                                </div>

                                                                <div
                                                                    style={
                                                                        styles.actionsRow
                                                                    }
                                                                >
                                                                    <button
                                                                        style={
                                                                            styles.pinBtn
                                                                        }
                                                                        onClick={() =>
                                                                            togglePin(
                                                                                c.id
                                                                            )
                                                                        }
                                                                    >
                                                                        📌{" "}
                                                                        {c.pinned
                                                                            ? "Unpin"
                                                                            : "Pin"}
                                                                    </button>
                                                                    <button
                                                                        style={
                                                                            styles.deleteBtn
                                                                        }
                                                                        onClick={() =>
                                                                            deleteComment(
                                                                                c.id
                                                                            )
                                                                        }
                                                                    >
                                                                        🗑 Delete
                                                                    </button>
                                                                </div>
                                                            </div>
                                                        ))}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}

                                {/* DELETED COMMENTS */}
                                {deletedLogs.length > 0 && (
                                    <>
                                        <h3 style={styles.deletedTitle}>
                                            Deleted Comments (Audit Log)
                                        </h3>
                                        <div style={styles.deletedGrid}>
                                            {deletedLogs.map((d) => (
                                                <div
                                                    key={d.id}
                                                    style={
                                                        styles.deletedCard
                                                    }
                                                >
                                                    <div
                                                        style={
                                                            styles.deletedHeaderRow
                                                        }
                                                    >
                                                        <span>
                                                            👤 @
                                                            {
                                                                d.ownerUsername
                                                            }
                                                        </span>
                                                    </div>

                                                    <p
                                                        style={
                                                            styles.deletedContent
                                                        }
                                                    >
                                                        🔒 {d.originalContent}
                                                    </p>

                                                    <p style={styles.reason}>
                                                        Reason: {d.deleteReason}
                                                    </p>

                                                    <div
                                                        style={
                                                            styles.deletedMetaRow
                                                        }
                                                    >
                                                        <span>
                                                            🧑‍🔬 @
                                                            {
                                                                d.deletedByUsername
                                                            }
                                                        </span>
                                                        <span>
                                                            {d.deletedAt}
                                                        </span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </>
                                )}
                            </>
                        )}

                        {activeTab === "logs" && (
                            <div style={styles.logsWrapper}>
                                <div style={styles.logCard}>
                                    <h3 style={styles.logTitle}>
                                        Researcher Action Logs
                                    </h3>

                                    <div style={styles.logContainer}>
                                        {researcherLogs.length === 0 ? (
                                            <p style={styles.noComments}>
                                                No logs recorded for this task
                                                yet.
                                            </p>
                                        ) : (
                                            researcherLogs.map(
                                                (log, index) => (
                                                    <div
                                                        key={index}
                                                        style={styles.logRow}
                                                    >
                                                        <div
                                                            style={
                                                                styles.timeCol
                                                            }
                                                        >
