                                                                    styles.actionType
                                                                }
                                                            >
                                                                {log.action}
                                                            </span>

                                                            {log.targetUsername && (
                                                                <span
                                                                    style={
                                                                        styles.targetUser
                                                                    }
                                                                >
                                                                    →
                                                                    @
                                                                    {
                                                                        log.targetUsername
                                                                    }
                                                                </span>
                                                            )}

                                                            {log.commentId && (
                                                                <span
                                                                    style={
                                                                        styles.commentId
                                                                    }
                                                                >
                                                                    (comment #
                                                                    {
                                                                        log.commentId
                                                                    }
                                                                    )
                                                                </span>
                                                            )}
                                                        </div>

                                                        <div
                                                            style={
                                                                styles.userCol
                                                            }
                                                        >
                                                            @
                                                            {
                                                                log.researcherUsername
                                                            }
                                                        </div>
                                                    </div>
                                                )
                                            )
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}
                    </>
                )}
            </div>

            {/* KEYFRAMES */}
            <style>
                {`
                @keyframes floatParticle {
                    0% { transform: translateY(0); opacity: .4; }
                    50% { opacity: 1; }
                    100% { transform: translateY(-120vh); opacity: 0; }
                }
                `}
            </style>
        </div>
    );
}

